def parse_id_set_from_env(name: str) -> set[int]:
    ids = set()
    raw = os.getenv(name, "") or ""
    raw = raw.replace(";", ",")
    raw = raw.replace("\n", ",")
    for part in raw.split(","):
        part = part.strip()
        if part and part.lstrip("-").isdigit():
            ids.add(int(part))
    return ids


