async def publish_copy_structure_edge_signal(trade: dict) -> dict:
    """Send the FINAL Trendline Edge execution after the prior M1 candle has closed.

    The pair was already pre-armed before the boundary. This execute packet has a strict
    two-second validity window and carries the new-candle open/displacement audit fields.
    """
    if not COPY_SEND_STRUCTURE_EDGE:
        return {"ok": False, "skipped": True, "reason": "COPY_SEND_STRUCTURE_EDGE=false"}
    try:
        entry_bucket = int(float((trade or {}).get("entry_bucket") or 0))
        if entry_bucket <= 0:
            return {"ok": False, "skipped": True, "reason": "missing entry_bucket"}
        pair = str((trade or {}).get("pair") or "").strip()
        direction = str((trade or {}).get("direction") or "").strip().upper()
        symbol = str((trade or {}).get("symbol") or "").strip()
        if not pair or direction not in {"CALL", "PUT"}:
            return {"ok": False, "skipped": True, "reason": "missing pair/direction"}
        entry_dt = datetime.fromtimestamp(entry_bucket, tz=UTC)
        expiry_dt = entry_dt + timedelta(seconds=60)
        max_delay = int(TRENDLINE_EXECUTION_MAX_DELAY_SECONDS)
        payload = {
            "ok": True,
            "id": f"structure_{safe_key(pair)}_{entry_bucket}_{direction}_{safe_key((trade or {}).get('setup'))}",
            "pair": pair,
            "pair_display": pair,
            "symbol": symbol or None,
            "platform_symbol": symbol or pair,
            "direction": direction,
            "timeframe": "M1",
            "duration_seconds": 60,
            "duration_minutes": 1,
            "entry_time": entry_dt.isoformat(),
            "expires_at": (entry_dt + timedelta(seconds=max_delay)).isoformat(),
            "expiry_time": expiry_dt.isoformat(),
            "expiry_timestamp": int(expiry_dt.timestamp()),
            "trade_expiry_mode": "absolute_time",
            "entry_mode": "instant",
            "copy_entry_mode": "instant",
            "execution_mode": "instant_demo_test",
            "immediate_entry": True,
            "direct_entry": True,
            "instant_entry": True,
            "allow_background_entry": True,
            "max_entry_delay_seconds": max_delay,
            "quality": (trade or {}).get("score"),
            "confidence": (trade or {}).get("score"),
            "entry_price": (trade or {}).get("entry_price") or (trade or {}).get("price"),
            "payout": (trade or {}).get("payout"),
            "structure_setup": (trade or {}).get("setup"),
            "structure_score": (trade or {}).get("score"),
            "m5_bias": (trade or {}).get("m5_bias"),
            "m5_strength": (trade or {}).get("m5_strength"),
            "structure_confluences": list((trade or {}).get("confluences") or [])[:8],
            "trendline_prearm": True,
            "trendline_target_bucket": entry_bucket,
            "trendline_candle_open": (trade or {}).get("trendline_candle_open"),
            "trendline_signal_price": (trade or {}).get("trendline_signal_price") or (trade or {}).get("entry_price") or (trade or {}).get("price"),
            "trendline_entry_displacement_atr": (trade or {}).get("trendline_entry_displacement_atr"),
            "trendline_prearmed_at": (trade or {}).get("prearmed_at"),
            "stat_model_confidence": None,
            "stat_model_support": None,
            "stat_model_pairs": None,
            "stat_local_probability": None,
            "stat_local_support": None,
            "demo_only": True,
            "creator_user_id": int(ADMIN_TELEGRAM_ID),
            "target_user_id": int(ADMIN_TELEGRAM_ID),
            "note": f"trendline_edge_v2_prearm | setup={(trade or {}).get('setup')} | score={(trade or {}).get('score')} | line={(trade or {}).get('line_type')} | touches={(trade or {}).get('line_touches')} | demo_only",
        }
        result = await publish_copy_trading_signal(payload, source="structure_edge")
        logger.info("Copy Trading Trendline Edge FINAL sent | pair=%s | setup=%s | score=%s | delivery=%s", pair, (trade or {}).get("setup"), (trade or {}).get("score"), result.get("delivery") if isinstance(result, dict) else result)
        return result
    except Exception as exc:
        logger.exception("Trendline Edge final Copy publish failed: %s", exc)
        return {"ok": False, "error": str(exc)}


async def publish_copy_otc_edge_prepare_signal(pair: str, target_user_id: int | None = None, state: dict | None = None) -> dict:
    """Pre-select one watched pair only in the extension linked to the watcher owner."""
    if not COPY_SEND_OTC_EDGE or not COPY_OTC_EDGE_PREPARE_ENABLED:
        return {"ok": False, "skipped": True, "reason": "OTC Edge prepare disabled"}
    try:
        state = state if isinstance(state, dict) else None
        target_uid = normalize_copy_telegram_user_id(
            target_user_id
            or ((state or {}).get("owner_user_id"))
            or ((state or {}).get("started_by"))
            or ((state or {}).get("chat_id"))
            or ADMIN_TELEGRAM_ID
        )
        resolved_pair, symbol = _otc_edge_resolve_pair_text(pair) if "_otc_edge_resolve_pair_text" in globals() else (pair, get_otc_symbol_for_pair(pair))
        resolved_pair = str(resolved_pair or pair or "").strip()
        symbol = symbol or get_otc_symbol_for_pair(resolved_pair)
        if not resolved_pair or not symbol:
            return {"ok": False, "skipped": True, "reason": "pair could not be resolved"}

        now_dt = now_utc()
        timing = _otc_edge_current_candle_timing() if "_otc_edge_current_candle_timing" in globals() else {}
        close_dt = timing.get("close_dt")
        if close_dt:
            expiry_dt = close_dt.astimezone(UTC)
        else:
            expiry_dt = datetime.fromtimestamp(((int(now_dt.timestamp()) // 60) + 1) * 60, tz=UTC)

        user_key = safe_key(str(target_uid or "admin"))
        payload = {
            "ok": True,
            "id": f"edge_prepare_{user_key}_{safe_key(resolved_pair)}_{int(now_dt.timestamp()) // max(30, int(COPY_OTC_EDGE_PREPARE_REFRESH_SECONDS))}",
            "pair": resolved_pair,
            "pair_display": resolved_pair,
            "symbol": symbol,
            "platform_symbol": symbol,
            "direction": "CALL",
            "timeframe": "M1",
            "duration_seconds": 60,
            "duration_minutes": 1,
            "entry_time": now_dt.isoformat(),
            "expires_at": (now_dt + timedelta(seconds=60)).isoformat(),
            "expiry_time": expiry_dt.isoformat(),
            "expiry_timestamp": int(expiry_dt.timestamp()),
            "trade_expiry_mode": "m1_candle_close",
            "entry_mode": "prepare",
            "copy_entry_mode": "prepare",
            "execution_mode": "prepare_pair",
            "signal_kind": "otc_edge_prepare",
            "prepare_only": True,
            "preselected_pair_mode": True,
            "watch_pair": resolved_pair,
            "skip_asset_switch": False,
            "allow_background_entry": True,
            "creator_user_id": target_uid,
            "target_user_id": target_uid,
            "note": "otc_edge_engine | public_user_prepare | targeted",
        }
        result = await publish_copy_trading_signal(payload, source="otc_edge")
        logger.info("Copy Trading OTC Edge prepare sent | user=%s | pair=%s | result=%s", target_uid, resolved_pair, result)
        return result
    except Exception as e:
        logger.warning("OTC Edge prepare signal failed: %s", e)
        return {"ok": False, "error": str(e)}




async def publish_copy_otc_edge_signal(item: dict, target_user_id: int | None = None, state: dict | None = None) -> dict:
    """Send an OTC Edge signal only to the extension linked to the watcher owner."""
    if not COPY_SEND_OTC_EDGE:
        return {"ok": False, "skipped": True, "reason": "COPY_SEND_OTC_EDGE=false"}
    try:
        item = dict(item or {})
        state = state if isinstance(state, dict) else None
        target_uid = normalize_copy_telegram_user_id(
            target_user_id
            or ((state or {}).get("owner_user_id"))
            or ((state or {}).get("started_by"))
            or ((state or {}).get("chat_id"))
            or ADMIN_TELEGRAM_ID
        )
        pair = str(item.get("pair") or "").strip()
        direction = str(item.get("direction") or "").strip().upper()
        symbol = item.get("symbol") or get_otc_symbol_for_pair(pair)
        if not pair or direction not in {"CALL", "PUT"}:
            return {"ok": False, "skipped": True, "reason": "missing pair/direction"}

        timing = _otc_edge_current_candle_timing() if "_otc_edge_current_candle_timing" in globals() else {}
        now_dt = now_utc()
        if _otc_edge_timing_mode() == "m1_candle_close" and timing.get("close_dt"):
            expiry_dt = timing.get("close_dt").astimezone(UTC)
            expiry_timestamp = int(expiry_dt.timestamp())
            entry_dt = now_dt
            duration_seconds = max(5, expiry_timestamp - int(now_dt.timestamp()))
            trade_expiry_mode = "m1_candle_close"
        else:
            entry_dt = now_dt
            expiry_timestamp = int(now_dt.timestamp()) + int(OTC_EDGE_WATCHER_TRADE_DURATION_SECONDS)
            expiry_dt = datetime.fromtimestamp(expiry_timestamp, tz=UTC)
            duration_seconds = int(OTC_EDGE_WATCHER_TRADE_DURATION_SECONDS)
            trade_expiry_mode = "fixed_60s"

        watcher_state = state or _otc_edge_get_state(target_uid) or {}
        pairs = list(watcher_state.get("pairs") or [])
        single_pair_mode = bool(
            str(watcher_state.get("mode") or "") == "pairs"
            and len(pairs) == 1
            and str(pairs[0]) == pair
        )
        user_key = safe_key(str(target_uid or "admin"))
        payload = {
            "ok": True,
            "id": f"edge_{user_key}_{safe_key(pair)}_{int(entry_dt.timestamp())}_{direction}_{safe_key(item.get('pattern'))}",
            "pair": pair,
            "pair_display": pair,
            "symbol": symbol,
            "platform_symbol": symbol,
            "direction": direction,
            "timeframe": "M1",
            "duration_seconds": max(5, int(duration_seconds)),
            "duration_minutes": 1,
            "entry_time": entry_dt.isoformat(),
            "expires_at": (entry_dt + timedelta(seconds=COPY_SOURCE_MAX_ENTRY_DELAY_SECONDS["otc_edge"])).isoformat(),
            "expiry_time": expiry_dt.isoformat(),
            "expiry_timestamp": expiry_timestamp,
            "trade_expiry_mode": trade_expiry_mode,
            "quality": int(item.get("score", 0) or 0),
            "confidence": int(item.get("score", 0) or 0),
            "entry_price": item.get("price"),
            "payout": item.get("payout"),
            "entry_mode": "instant",
            "copy_entry_mode": "instant",
            "execution_mode": "direct",
            "immediate_entry": True,
            "direct_entry": True,
            "allow_background_entry": True,
            "max_entry_delay_seconds": COPY_SOURCE_MAX_ENTRY_DELAY_SECONDS["otc_edge"],
            "preselected_pair_mode": single_pair_mode,
            "watch_pair": pair if single_pair_mode else None,
            "skip_asset_switch": single_pair_mode,
            "creator_user_id": target_uid,
            "target_user_id": target_uid,
            "note": f"otc_edge_engine | targeted_user={target_uid} | direct_entry | exact_expiry | preselected={single_pair_mode} | pattern={item.get('pattern') or item.get('reason') or '-'}",
        }
        result = await publish_copy_trading_signal(payload, source="otc_edge")
        logger.info("Copy Trading OTC Edge sent | user=%s | pair=%s | expiry=%s | preselected=%s | result=%s", target_uid, pair, expiry_timestamp, single_pair_mode, result)
        return result
    except Exception as e:
        logger.warning("OTC Edge Copy signal failed: %s", e)
        return {"ok": False, "error": str(e)}




async def publish_copy_trading_room_signal(trade: dict, state: dict | None = None, creator_user_id=None) -> dict:
    """Send Trading Room entries to the extension as source=trading_room."""
    if not COPY_SEND_TRADING_ROOM:
        return {"ok": False, "skipped": True, "reason": "COPY_SEND_TRADING_ROOM=false"}
    if not is_copy_signal_creator_allowed(creator_user_id):
        logger.info("Copy Trading blocked trading-room user signal | user_id=%s", creator_user_id)
        return copy_signal_guard_skip_payload(creator_user_id)
    try:
        entry_ts = float((trade or {}).get("entry_ts") or 0)
        if entry_ts <= 0:
            return {"ok": False, "skipped": True, "reason": "missing entry_ts"}
        entry_dt = datetime.fromtimestamp(entry_ts, tz=UTC)
        pair = str((trade or {}).get("pair") or (state or {}).get("pair") or "").strip()
        direction = str((trade or {}).get("direction") or "").strip().upper()
        if not pair or direction not in {"CALL", "PUT"}:
            return {"ok": False, "skipped": True, "reason": "missing pair/direction"}
        payload = {
            "ok": True,
            "id": f"room_{safe_key(pair)}_{int(entry_ts)}_{direction}_{safe_key((trade or {}).get('setup_kind'))}",
            "pair": pair,
            "pair_display": pair,
            "symbol": (trade or {}).get("symbol") or (state or {}).get("symbol"),
            "platform_symbol": (trade or {}).get("symbol") or (state or {}).get("symbol"),
            "direction": direction,
            "timeframe": "M1",
            "duration_seconds": 60,
            "duration_minutes": 1,
            "entry_time": entry_dt.isoformat(),
            "expires_at": (
                entry_dt
                + timedelta(seconds=COPY_SOURCE_MAX_ENTRY_DELAY_SECONDS["trading_room"])
            ).isoformat(),
            "quality": (trade or {}).get("score"),
            "confidence": (trade or {}).get("score"),
            "entry_price": (trade or {}).get("price"),
            "payout": (trade or {}).get("payout"),
            "note": str((trade or {}).get("setup") or (trade or {}).get("setup_kind") or "trading_room")[:500],
            "creator_user_id": int(creator_user_id) if creator_user_id is not None else None,
            "target_user_id": int(creator_user_id) if (COPY_USER_SIGNAL_ROUTING_ENABLED and creator_user_id is not None) else None,
        }
        result = await publish_copy_trading_signal(payload, source="trading_room")
        logger.info("Copy Trading trading-room sent | pair=%s | result=%s", pair, result)
        return result
    except Exception as e:
        logger.warning("Trading Room Copy signal failed: %s", e)
        return {"ok": False, "error": str(e)}


def format_dt_ar(iso_value: str):
    dt = parse_iso(iso_value)
    if not dt:
        return "غير متوفر"
    return dt.astimezone(UTC_PLUS_3).strftime("%Y-%m-%d %H:%M")


def get_user_record(user_id: int):
    uid = int(user_id)
    cached = _cache_get(f"user_record:{uid}", FIREBASE_USER_CACHE_TTL_SECONDS)
    if cached is not None:
        return cached
    data = users_ref().child(str(uid)).get()
    return _cache_set(f"user_record:{uid}", data)



def save_user_record(user_id: int, data: dict):
    uid = int(user_id)
    data = dict(data or {})

    # لا نكتب last_seen على Firebase مع كل رسالة؛ هذا كان يسبب writes كثيرة بلا فائدة.
    critical_keys = {
        "status", "quotex_id", "expires_at", "trial_used", "trial_source",
        "approved", "pending", "role", "rejected_at", "revoked_at", "blocked_at",
        "updated_at",
    }
    has_critical_update = any(k in data for k in critical_keys)

    if not has_critical_update and set(data.keys()).issubset({"telegram_id", "name", "username", "last_seen"}):
        last_key = f"last_seen_write:{uid}"
        last_write = _cache_get(last_key, SAVE_USER_LAST_SEEN_THROTTLE_SECONDS)
        if last_write is not None:
            # حدّث الكاش فقط، لا تكتب Firebase.
            cached = _cache_get(f"user_record:{uid}", FIREBASE_USER_CACHE_TTL_SECONDS) or {}
            if isinstance(cached, dict):
                cached.update(data)
                _cache_set(f"user_record:{uid}", cached)
            return
        _cache_set(last_key, True)

    users_ref().child(str(uid)).update(data)

    cached = _cache_get(f"user_record:{uid}", FIREBASE_USER_CACHE_TTL_SECONDS) or {}
    if isinstance(cached, dict):
        cached.update(data)
        _cache_set(f"user_record:{uid}", cached)
    else:
        _cache_set(f"user_record:{uid}", data)

    clear_users_list_cache()



def save_pending_user(user_id: int, data: dict):
    uid = int(user_id)
    data = dict(data or {})

    # لا نحذف سجل التجربة ولا نمسح المستخدم بالكامل عند تقديم طلب جديد.
    # فقط نلغي أي تفعيل قديم ونحفظ الطلب المعلق.
    try:
        approved_ref().child(str(uid)).delete()
    except Exception:
        logger.debug("Suppressed exception at line 3077", exc_info=True)

    pending_ref().child(str(uid)).set(data)
    users_ref().child(str(uid)).update({
        "telegram_id": uid,
        "name": data.get("name", ""),
        "username": data.get("username", ""),
        "quotex_id": data.get("quotex_id", ""),
        "status": "pending",
        "pending": True,
        "updated_at": now_iso(),
    })

    clear_user_cache(uid)
    clear_pending_list_cache()
    clear_approved_list_cache()
    clear_users_list_cache()
    _cache_set(f"user_status:{uid}", "pending")
    _cache_set(f"approved:{uid}", False)



def remove_pending_user(user_id: int):
    uid = int(user_id)
    try:
        pending_ref().child(str(uid)).delete()
    except Exception:
        logger.debug("Suppressed exception at line 3104", exc_info=True)
    clear_pending_list_cache()
    clear_user_cache(uid)



def set_approved_user(user_id: int, data: dict):
    uid = int(user_id)
    data = dict(data or {})
    approved_ref().child(str(uid)).set(data)
    clear_user_cache(uid)
    clear_approved_list_cache()
    _cache_set(f"approved_data:{uid}", data)
    _cache_set(f"approved:{uid}", str(data.get("status", "approved")) == "approved")
    if str(data.get("status", "approved")) == "approved":
        _cache_set(f"user_status:{uid}", "approved")



