OTC_EDGE_MIN_PAYOUT = int(os.getenv("OTC_EDGE_MIN_PAYOUT", str(OTC_LIVE_MIN_PAYOUT)))
OTC_EDGE_TICK_MAX_AGE_SECONDS = int(os.getenv("OTC_EDGE_TICK_MAX_AGE_SECONDS", "20"))
