    keep = (
        "ok", "status", "pair", "symbol", "direction", "score", "pattern", "reason",
        "detail", "risk", "price", "payout", "tick_age", "metrics", "history", "candidates",
    )
    return json.loads(json.dumps({k: item.get(k) for k in keep}, ensure_ascii=False, default=str))


