def _three_candle_direction_icon(direction: str) -> str:
    direction = str(direction or "").upper()
    if direction == "CALL":
        return "🟢 CALL"
    if direction == "PUT":
        return "🔴 PUT"
    return "⚪"


def _three_candle_result_for_direction(direction: str, open_price, close_price) -> str:
    try:
        o = float(open_price)
        c = float(close_price)
        if abs(c - o) <= float(THREE_CANDLE_TIE_EPSILON):
            return "draw"
        direction = str(direction or "").upper()
        if direction == "CALL":
            return "win" if c > o else "loss"
        if direction == "PUT":
            return "win" if c < o else "loss"
        return "unknown"
    except Exception:
        return "unknown"


def _three_candle_bucket_now() -> tuple[int, float]:
    now_ts = time_module.time()
    bucket_ts = int(now_ts // 60) * 60
    remaining = float(bucket_ts + 60 - now_ts)
    return bucket_ts, remaining


def _three_candle_get_sorted_candles(symbol: str) -> list[dict]:
    try:
        with quotex_otc_feed.lock:
            candles_map = dict((quotex_otc_feed.candles.get(symbol) or {}))
        return [dict(c) for _, c in sorted(candles_map.items())]
    except Exception:
        return []


def _three_candle_pair_on_cooldown(pair: str) -> tuple[bool, int]:
    try:
        now_ts = time_module.time()
        until_ts = float((_three_candle_channel_state.get("pair_cooldowns") or {}).get(pair, 0) or 0)
        if until_ts > now_ts:
            return True, int(round(until_ts - now_ts))
        if until_ts:
            (_three_candle_channel_state.get("pair_cooldowns") or {}).pop(pair, None)
        return False, 0
    except Exception:
        return False, 0


def _three_candle_pair_signal_block_remaining(pair: str) -> int:
    """Return how many upcoming published signals must pass before this pair may be used again."""
    try:
        blocks = _three_candle_channel_state.setdefault("pair_signal_blocks", {})
        remaining = int(blocks.get(pair, 0) or 0)
        if remaining <= 0:
            blocks.pop(pair, None)
            return 0
        return remaining
    except Exception:
        return 0


def _three_candle_note_published_pair(pair: str):
    """Block the just-used pair for the next N published three-candle signals.

    v1.02 uses N=1: after EUR/CHF gets a signal, the very next published signal
    must be on another pair. A second consecutive final loss escalates to cooldown.
    """
    try:
        pair = str(pair or "").strip()
        if not pair:
            return
        blocks = _three_candle_channel_state.setdefault("pair_signal_blocks", {})
        for p in list(blocks.keys()):
            if p == pair:
                continue
            try:
                blocks[p] = int(blocks.get(p, 0) or 0) - 1
            except Exception:
                blocks[p] = 0
            if int(blocks.get(p, 0) or 0) <= 0:
                blocks.pop(p, None)
        block_count = max(0, int(THREE_CANDLE_PAIR_SIGNAL_BLOCK_COUNT))
        if block_count > 0:
            blocks[pair] = block_count
        else:
            blocks.pop(pair, None)
    except Exception:
        logger.debug("Suppressed exception at line 10851", exc_info=True)


def _three_candle_run_count_by_dir(by_bucket: dict, end_bucket: int, direction_value: int) -> tuple[int, list[dict]]:
    """Count consecutive candles ending at end_bucket with the requested direction."""
    count = 0
    parts_list = []
    try:
        bucket = int(end_bucket)
        direction_value = 1 if int(direction_value) > 0 else -1
        while True:
            candle = by_bucket.get(int(bucket))
            if not candle:
                break
            parts = _otc_edge_candle_parts(candle)
            if int(parts.get("dir", 0) or 0) != direction_value:
                break
            count += 1
            parts_list.append(parts)
            bucket -= 60
        return count, parts_list
    except Exception:
        return count, parts_list


def _three_candle_avg_body_score(parts_list: list[dict]) -> float:
    try:
        vals = [float((p or {}).get("body_ratio", 0) or 0) for p in parts_list if isinstance(p, dict)]
        if not vals:
            return 0.0
        return round(sum(vals) / len(vals), 4)
    except Exception:
        return 0.0


def _three_candle_register_final_result(pair: str, result: str):
    """Register final pair quality and escalate repeat protection after losses.

    v1.02 policy:
    - Normal signal: the pair is only prevented from being the very next published signal.
    - Second consecutive final loss: the normal one-signal block is removed and replaced by
      the 30-minute cooldown. After the cooldown expires, the pair is immediately eligible
      again without an extra signal-count block.
    """
    try:
        pair = str(pair or "").strip()
        if not pair:
            return
        streaks = _three_candle_channel_state.setdefault("pair_loss_streaks", {})
        cooldowns = _three_candle_channel_state.setdefault("pair_cooldowns", {})
        blocks = _three_candle_channel_state.setdefault("pair_signal_blocks", {})
        if result == "loss":
            streaks[pair] = int(streaks.get(pair, 0) or 0) + 1
            if int(streaks[pair]) >= int(THREE_CANDLE_PAIR_LOSS_LIMIT):
                # Escalation replaces the normal anti-repeat block; the two gates do not stack.
                blocks.pop(pair, None)
                cooldowns[pair] = time_module.time() + int(THREE_CANDLE_PAIR_COOLDOWN_SECONDS)
                streaks[pair] = 0
        elif result in {"win", "draw"}:
            streaks[pair] = 0
    except Exception:
        logger.debug("Suppressed exception at line 10898", exc_info=True)



def _three_candle_result_outcome(result_type: str) -> str:
    result_type = str(result_type or "").strip().lower()
    if result_type in {"direct_win", "mg_win", "win"}:
        return "win"
    if result_type in {"loss", "lose"}:
        return "loss"
    if result_type in {"draw", "doji", "tie"}:
        return "draw"
    return "unknown"


def _three_candle_initial_outcome(result_type: str) -> str:
    """Quality of the original entry before any MG1 rescue."""
    result_type = str(result_type or "").strip().lower()
    if result_type == "direct_win":
        return "win"
    if result_type in {"mg_win", "loss"}:
        return "loss"
    if result_type == "draw":
        return "draw"
    return "unknown"


def _three_candle_payout_band(payout) -> str:
    try:
        p = int(float(payout or 0))
    except Exception:
        p = 0
    if p <= 0:
        return "غير معروف"
    if p < 80:
        return "<80"
    if p < 85:
        return "80-84"
    if p < 90:
        return "85-89"
    if p < 95:
        return "90-94"
    return "95+"


def _three_candle_hour_label(bucket_ts) -> str:
    try:
        dt = datetime.fromtimestamp(int(bucket_ts), tz=UTC).astimezone(UTC_PLUS_3)
        return f"{dt.strftime('%H')}:00"
    except Exception:
        return "غير معروف"


def _three_candle_float(v, default=0.0, digits=4):
    try:
        return round(float(v), int(digits))
    except Exception:
        return default


def _three_candle_build_memory_record(trade: dict, result_type: str, result_text: str, candle: dict | None = None) -> dict:
    trade = trade or {}
    candle = candle or {}
    outcome = _three_candle_result_outcome(result_type)
    initial_outcome = _three_candle_initial_outcome(result_type)
    entry_bucket = int(trade.get("entry_bucket") or 0)
    try:
        entry_dt = datetime.fromtimestamp(entry_bucket, tz=UTC).astimezone(UTC_PLUS_3) if entry_bucket else now_utc().astimezone(UTC_PLUS_3)
    except Exception:
        entry_dt = now_utc().astimezone(UTC_PLUS_3)
    record = {
        "created_at": now_iso(),
        "day": get_utc3_day_key(),
        "entry_hour": int(entry_dt.strftime("%H")),
        "entry_hour_label": _three_candle_hour_label(entry_bucket),
        "pair": str(trade.get("pair", "")),
        "symbol": str(trade.get("symbol", "")),
        "direction": str(trade.get("direction", "")).upper(),
        "result_type": str(result_type),
        "outcome": outcome,
        "initial_outcome": initial_outcome,
        "result_text": str(result_text),
        "payout": safe_int(trade.get("payout", 0), 0),
        "payout_band": _three_candle_payout_band(trade.get("payout", 0)),
        "pattern": str(trade.get("pattern") or "unknown"),
        "pattern_ar": str(trade.get("pattern_ar") or ""),
        "momentum_count": safe_int(trade.get("momentum_count", 0), 0),
        "correction_count": safe_int(trade.get("correction_count", 0), 0),
        "body_score": _three_candle_float(trade.get("body_score", 0), 0.0, 4),
        "momentum_body_score": _three_candle_float(trade.get("momentum_body_score", 0), 0.0, 4),
        "correction_body_score": _three_candle_float(trade.get("correction_body_score", 0), 0.0, 4),
        "confirm_body_ratio": _three_candle_float(trade.get("confirm_body_ratio", 0), 0.0, 4),
        "confirm_upper_wick": _three_candle_float(trade.get("confirm_upper_wick", 0), 0.0, 4),
        "confirm_lower_wick": _three_candle_float(trade.get("confirm_lower_wick", 0), 0.0, 4),
        "entry_bucket": entry_bucket,
        "step": safe_int(trade.get("step", 0), 0),
        "martingale": str(result_type) == "mg_win",
        "test_mode": bool(trade.get("test_mode", True)),
        "source_version": "v0.66_memory_optimized",
    }
    if candle:
        record.update({
            "result_open": _three_candle_float(candle.get("open", 0), 0.0, 6),
            "result_close": _three_candle_float(candle.get("close", 0), 0.0, 6),
            "result_high": _three_candle_float(candle.get("high", 0), 0.0, 6),
            "result_low": _three_candle_float(candle.get("low", 0), 0.0, 6),
        })
    return record


def _three_candle_group_stats(records: list[dict], key_name: str) -> dict:
    groups = {}
    for r in records:
        key = str(r.get(key_name) or "غير معروف")
        g = groups.setdefault(key, {"key": key, "total": 0, "direct": 0, "mg": 0, "loss": 0, "draw": 0, "initial_win": 0, "initial_loss": 0})
        g["total"] += 1
        result_type = str(r.get("result_type") or "")
        outcome = str(r.get("outcome") or "")
        initial = str(r.get("initial_outcome") or "")
        if result_type == "direct_win":
            g["direct"] += 1
        elif result_type == "mg_win":
            g["mg"] += 1
        elif outcome == "loss":
            g["loss"] += 1
        elif outcome == "draw":
            g["draw"] += 1
        if initial == "win":
            g["initial_win"] += 1
        elif initial == "loss":
            g["initial_loss"] += 1
    for g in groups.values():
        total = max(1, int(g.get("total", 0)))
        decided_initial = max(1, int(g.get("initial_win", 0)) + int(g.get("initial_loss", 0)))
        final_wins = int(g.get("direct", 0)) + int(g.get("mg", 0))
        g["final_wr"] = round((final_wins / total) * 100, 1)
        g["initial_wr"] = round((int(g.get("initial_win", 0)) / decided_initial) * 100, 1)
        g["loss_rate"] = round((int(g.get("loss", 0)) / total) * 100, 1)
        # Score favors clean direct wins and penalizes final losses. MG wins are weak because the first entry failed.
        g["quality_score"] = round((int(g.get("direct", 0)) * 1.0 + int(g.get("mg", 0)) * 0.25 - int(g.get("loss", 0)) * 1.0) / total, 3)
    return groups


def _three_candle_format_group_lines(groups: dict, *, reverse: bool, limit: int = 5) -> str:
    try:
        min_sample = max(1, int(THREE_CANDLE_MEMORY_MIN_GROUP_SAMPLE))
        rows = [g for g in groups.values() if int(g.get("total", 0)) >= min_sample]
        rows.sort(key=lambda g: (float(g.get("quality_score", 0)), float(g.get("initial_wr", 0)), int(g.get("total", 0))), reverse=reverse)
        lines = []
        for g in rows[:int(limit)]:
            lines.append(
                f"• {g.get('key')}: {g.get('total')} صفقات | دخول أول {g.get('initial_wr')}% | نهائي {g.get('final_wr')}% | خسارة {g.get('loss_rate')}%"
            )
        return "\n".join(lines) if lines else "لا يوجد عيّنة كافية بعد."
    except Exception:
        return "تعذر تنسيق التقرير."


def build_three_candle_strategy_memory_report(limit: int | None = None) -> str:
    if limit is None:
        limit = int(THREE_CANDLE_MEMORY_REPORT_LIMIT)
    limit = max(1, int(limit))
    records = _three_candle_fetch_result_records(limit=limit)
    records = [r for r in records if str(r.get("result_type") or "") in {"direct_win", "mg_win", "loss", "draw"}]
    total = len(records)
    if not total:
        return "🧠 ذاكرة استراتيجية 3 شموع\n━━━━━━━━━━━━━━\nلا يوجد نتائج كافية بعد. خلّي القناة تجمع صفقات جديدة أولاً."

    direct_win = sum(1 for r in records if r.get("result_type") == "direct_win")
    mg_win = sum(1 for r in records if r.get("result_type") == "mg_win")
    loss = sum(1 for r in records if r.get("result_type") == "loss")
    draw = sum(1 for r in records if r.get("result_type") == "draw")
    initial_wins = sum(1 for r in records if r.get("initial_outcome") == "win")
    initial_losses = sum(1 for r in records if r.get("initial_outcome") == "loss")
    initial_total = max(1, initial_wins + initial_losses)
    final_wins = direct_win + mg_win
    initial_wr = round((initial_wins / initial_total) * 100, 1)
    final_wr = round((final_wins / max(1, total)) * 100, 1)

    pair_groups = _three_candle_group_stats(records, "pair")
    pattern_groups = _three_candle_group_stats(records, "pattern")
    correction_groups = _three_candle_group_stats(records, "correction_count")
    momentum_groups = _three_candle_group_stats(records, "momentum_count")
    hour_groups = _three_candle_group_stats(records, "entry_hour_label")
    payout_groups = _three_candle_group_stats(records, "payout_band")

    return (
        "🧠 ذاكرة استراتيجية 3 شموع\n"
        "━━━━━━━━━━━━━━\n"
        f"📌 العينة: آخر {total} نتيجة\n"
        f"✅ Win مباشر: {direct_win}\n"
        f"✅ Win MG1: {mg_win}\n"
        f"💔 Loss: {loss}\n"
        f"🟰 Draw: {draw}\n"
        f"🎯 جودة الدخول الأول: {initial_wr}%\n"
        f"📈 النتيجة النهائية بعد MG1: {final_wr}%\n\n"
        "✅ أفضل الأزواج مبدئياً:\n"
        f"{_three_candle_format_group_lines(pair_groups, reverse=True, limit=4)}\n\n"
        "⚠️ أسوأ الأزواج مبدئياً:\n"
        f"{_three_candle_format_group_lines(pair_groups, reverse=False, limit=4)}\n\n"
        "📊 حسب النمط:\n"
        f"{_three_candle_format_group_lines(pattern_groups, reverse=True, limit=4)}\n\n"
        "🔁 حسب عدد التصحيح:\n"
        f"{_three_candle_format_group_lines(correction_groups, reverse=True, limit=4)}\n\n"
        "🔥 حسب قوة المومنتم:\n"
        f"{_three_candle_format_group_lines(momentum_groups, reverse=True, limit=4)}\n\n"
        "⏰ حسب الساعة:\n"
        f"{_three_candle_format_group_lines(hour_groups, reverse=True, limit=4)}\n\n"
        "💰 حسب payout:\n"
        f"{_three_candle_format_group_lines(payout_groups, reverse=True, limit=4)}\n\n"
        "ملاحظة: v0.66 يستخدم ذاكرة مضغوطة وقراءات محدودة مع فلتر متوازن."
    )[:3900]

def _three_candle_compact_memory_record(record: dict) -> dict:
    """Keep only fields required by reports/current filters plus compact quality features."""
    record = record or {}
    allowed = (
        "created_at", "day", "entry_hour", "entry_hour_label", "pair", "symbol", "direction",
        "result_type", "outcome", "initial_outcome", "payout", "payout_band", "pattern",
        "momentum_count", "correction_count", "body_score", "momentum_body_score",
        "correction_body_score", "confirm_body_ratio", "confirm_upper_wick", "confirm_lower_wick",
        "martingale", "source_version",
    )
    compact = {key: record.get(key) for key in allowed if key in record}
    compact["source_version"] = "v0.66_memory_optimized"
    return compact


def _three_candle_query_last_dict(ref, limit: int) -> dict:
    """Server-side bounded query. Never falls back to a full-path .get()."""
    try:
        limit = max(1, int(limit))
        data = ref.order_by_key().limit_to_last(limit).get() or {}
        return data if isinstance(data, dict) else {}
    except Exception as e:
        logger.exception("Could not run limited Firebase query for three-candle memory: %s", e)
        return {}


def _three_candle_records_from_dict(data: dict) -> list[dict]:
    items = []
    for key, value in (data or {}).items():
        if isinstance(value, dict):
            item = dict(value)
            item["_key"] = str(key)
            items.append(item)
    # Keys begin with millisecond timestamps, making key order the most reliable order.
    items.sort(key=lambda row: str(row.get("_key", "")))
    return items


def _three_candle_try_migrate_legacy_memory(limit: int) -> list[dict]:
    """One-time bounded migration of the newest legacy records into compact memory_v2."""
    try:
        if _three_candle_channel_state.get("memory_migration_checked"):
            return []
        _three_candle_channel_state["memory_migration_checked"] = True
        if not bool(THREE_CANDLE_MEMORY_MIGRATE_LEGACY):
            return []

        migrated_flag = bool((_three_candle_memory_meta_ref().child("legacy_migrated").get() or False))
        if migrated_flag:
            return []

        legacy_data = _three_candle_query_last_dict(_three_candle_results_ref(), limit)
        legacy_rows = _three_candle_records_from_dict(legacy_data)
        updates = {}
        migrated_rows = []
        for row in legacy_rows:
            key = str(row.get("_key") or "").strip()
            if not key:
                continue
            compact = _three_candle_compact_memory_record(row)
            compact["migrated_from_legacy"] = True
            updates[key] = compact
            item = dict(compact)
            item["_key"] = key
            migrated_rows.append(item)
        if updates:
            _three_candle_memory_ref().update(updates)
        _three_candle_memory_meta_ref().update({
            "legacy_migrated": True,
            "legacy_migrated_count": len(updates),
            "legacy_migrated_at": now_iso(),
            "version": "v0.66",
        })
        _three_candle_channel_state["memory_legacy_migrated"] = len(updates)
        return migrated_rows
    except Exception as e:
        logger.exception("Could not migrate legacy three-candle memory: %s", e)
        return []


def _three_candle_cache_append(record: dict, key: str):
    try:
        cache = list(_three_candle_channel_state.get("smart_records_cache") or [])
        item = dict(record or {})
        item["_key"] = str(key)
        cache = [row for row in cache if str(row.get("_key") or "") != str(key)]
        cache.append(item)
        cache.sort(key=lambda row: str(row.get("_key", "")))
        keep = max(
            1,
            int(THREE_CANDLE_MEMORY_QUERY_LIMIT),
            int(THREE_CANDLE_MEMORY_REPORT_LIMIT),
            int(THREE_CANDLE_SMART_PAIR_LOOKBACK),
        )
        cache = cache[-keep:]
        _three_candle_channel_state["smart_records_cache"] = cache
        _three_candle_channel_state["smart_records_cache_at"] = time_module.time()
        _three_candle_channel_state["smart_records_cache_limit"] = keep
    except Exception as e:
        logger.debug("Could not append three-candle memory cache: %s", e)


def _three_candle_record_result(trade: dict, result_type: str, result_text: str, candle: dict | None = None):
    try:
        if bool(THREE_CANDLE_MEMORY_ENABLED):
            detailed_record = _three_candle_build_memory_record(trade, result_type, result_text, candle=candle)
        else:
            detailed_record = {
                "created_at": now_iso(),
                "day": get_utc3_day_key(),
                "pair": str((trade or {}).get("pair", "")),
                "symbol": str((trade or {}).get("symbol", "")),
                "direction": str((trade or {}).get("direction", "")),
                "result_type": str(result_type),
                "result_text": str(result_text),
                "payout": safe_int((trade or {}).get("payout", 0), 0),
                "outcome": _three_candle_result_outcome(result_type),
                "initial_outcome": _three_candle_initial_outcome(result_type),
                "source_version": "v0.66_memory_optimized",
            }
        compact_record = _three_candle_compact_memory_record(detailed_record)
        key = f"{int(time_module.time() * 1000)}_{safe_key(compact_record.get('pair'))}"

        # One multi-location write: compact hot memory + optional cold detailed memory.
        update_payload = {f"{THREE_CANDLE_MEMORY_COMPACT_PATH}/{key}": compact_record}
        if bool(THREE_CANDLE_MEMORY_STORE_DETAILS):
            update_payload[f"{THREE_CANDLE_MEMORY_DETAILS_PATH}/{key}"] = detailed_record
        system_ref().child("three_candle_channel").update(update_payload)

        _three_candle_cache_append(compact_record, key)
        _three_candle_channel_state["memory_records_written"] = int(_three_candle_channel_state.get("memory_records_written", 0) or 0) + 1
    except Exception as e:
        logger.debug("Could not record three-candle result: %s", e)


def _three_candle_fetch_result_records(limit: int | None = None, force_refresh: bool = False) -> list[dict]:
    """Read only a bounded compact window, with a process cache refreshed locally after every result."""
    try:
        if limit is None:
            limit = max(int(THREE_CANDLE_MEMORY_REPORT_LIMIT), int(THREE_CANDLE_SMART_PAIR_LOOKBACK))
        limit = max(1, min(int(limit), max(1, int(THREE_CANDLE_MEMORY_QUERY_LIMIT))))

        now_ts = time_module.time()
        cache = list(_three_candle_channel_state.get("smart_records_cache") or [])
        cache_at = float(_three_candle_channel_state.get("smart_records_cache_at", 0) or 0)
        cache_limit = int(_three_candle_channel_state.get("smart_records_cache_limit", 0) or 0)
        if (
            not force_refresh
            and cache
            and cache_limit >= limit
            and (now_ts - cache_at) < max(1, int(THREE_CANDLE_SMART_MEMORY_CACHE_SECONDS))
        ):
            return cache[-limit:]

        data = _three_candle_query_last_dict(_three_candle_memory_ref(), limit)
        rows = _three_candle_records_from_dict(data)
        if not rows:
            rows = _three_candle_try_migrate_legacy_memory(limit)
            rows.sort(key=lambda row: str(row.get("_key", "")))

        _three_candle_channel_state["smart_records_cache"] = list(rows)
        _three_candle_channel_state["smart_records_cache_at"] = now_ts
        _three_candle_channel_state["smart_records_cache_limit"] = limit
        return rows[-limit:]
    except Exception as e:
        logger.exception("Could not fetch optimized three-candle memory records: %s", e)
        return []


def _three_candle_reset_strategy_memory() -> tuple[bool, str]:
    """Clear legacy, compact, detailed and metadata paths so reports/filters start truly fresh."""
    try:
        base_ref = system_ref().child("three_candle_channel")
        base_ref.update({
            "results": None,
            THREE_CANDLE_MEMORY_COMPACT_PATH: None,
            THREE_CANDLE_MEMORY_DETAILS_PATH: None,
            THREE_CANDLE_MEMORY_META_PATH: None,
        })
        _three_candle_channel_state["memory_records_written"] = 0
        _three_candle_channel_state["smart_records_cache"] = []
        _three_candle_channel_state["smart_records_cache_at"] = 0.0
        _three_candle_channel_state["smart_records_cache_limit"] = 0
        _three_candle_channel_state["memory_migration_checked"] = False
        _three_candle_channel_state["memory_legacy_migrated"] = 0
        _three_candle_channel_state["smart_filter_skips"] = 0
        _three_candle_channel_state["last_smart_skip"] = None
        _three_candle_channel_state["last_error"] = None
        return True, "✅ تم تصفير ذاكرة استراتيجية 3 شموع بالكامل. التقرير والفلتر سيحسبان من النتائج الجديدة فقط."
    except Exception as e:
        logger.exception("Could not reset three-candle strategy memory: %s", e)
        return False, "❌ تعذر تصفير الذاكرة. راجع اللوج."


def _three_candle_smart_record_decided(r: dict) -> bool:
    try:
        return str((r or {}).get("result_type") or "") in {"direct_win", "mg_win", "loss", "draw"}
    except Exception:
        return False


def _three_candle_get_smart_records_cached() -> list[dict]:
    """Shared bounded compact cache for the dynamic pair filter."""
    try:
        limit = max(1, int(THREE_CANDLE_SMART_PAIR_LOOKBACK))
        return [
            row for row in _three_candle_fetch_result_records(limit=limit)
            if _three_candle_smart_record_decided(row)
        ][-limit:]
    except Exception as e:
        logger.debug("Could not read smart records cache: %s", e)
        return []


def _three_candle_pair_recent_stats(pair: str, limit: int | None = None) -> dict:
    """Recent rolling stats for one pair. Recomputed every scan, so pair blocks are never permanent."""
    try:
        pair = str(pair or "").strip()
        if not pair:
            return {"total": 0}
        records = _three_candle_get_smart_records_cached()
        if limit is None:
            limit = int(THREE_CANDLE_SMART_PAIR_LOOKBACK)
        if limit and int(limit) > 0:
            records = records[-int(limit):]
        rows = [r for r in records if str(r.get("pair") or "").strip() == pair]
        total = len(rows)
        wins = sum(1 for r in rows if str(r.get("result_type") or "") in {"direct_win", "mg_win"})
        losses = sum(1 for r in rows if str(r.get("outcome") or "") == "loss" or str(r.get("result_type") or "") == "loss")
        draws = sum(1 for r in rows if str(r.get("outcome") or "") == "draw" or str(r.get("result_type") or "") == "draw")
        final_wr = round((wins / max(1, total)) * 100, 1) if total else 0.0
        loss_rate = round((losses / max(1, total)) * 100, 1) if total else 0.0
        return {"total": total, "wins": wins, "losses": losses, "draws": draws, "final_wr": final_wr, "loss_rate": loss_rate}
    except Exception as e:
        logger.debug("Could not build three-candle pair stats for %s: %s", pair, e)
        return {"total": 0, "error": str(e)}


def _three_candle_smart_pair_allowed(pair: str) -> tuple[bool, str]:
    try:
        if not bool(THREE_CANDLE_SMART_PAIR_FILTER_ENABLED):
            return True, "pair_filter_off"
        stats = _three_candle_pair_recent_stats(pair)
        sample = int(stats.get("total", 0) or 0)
        if sample < int(THREE_CANDLE_SMART_PAIR_MIN_SAMPLE):
            return True, f"pair_sample_low:{sample}"
        final_wr = float(stats.get("final_wr", 0) or 0)
        loss_rate = float(stats.get("loss_rate", 0) or 0)
        if final_wr < float(THREE_CANDLE_SMART_PAIR_MIN_FINAL_WR):
            return False, f"pair_recent_wr_low:{final_wr}%/{sample}"
        if loss_rate > float(THREE_CANDLE_SMART_PAIR_MAX_LOSS_RATE):
            return False, f"pair_recent_loss_high:{loss_rate}%/{sample}"
        return True, f"pair_ok:{final_wr}%/{sample}"
    except Exception as e:
        return True, f"pair_filter_error:{e}"


def _three_candle_apply_smart_filter(candidate: dict) -> dict | None:
    """v0.63 balanced test filter. It reduces weak setups without choking signal volume."""
    try:
        if not bool(THREE_CANDLE_SMART_FILTER_ENABLED):
            return candidate
        candidate = dict(candidate or {})
        reasons = []

        payout = int(float(candidate.get("payout", 0) or 0))
        if payout < int(THREE_CANDLE_SMART_MIN_PAYOUT):
            reasons.append(f"payout<{THREE_CANDLE_SMART_MIN_PAYOUT}:{payout}")

        allowed_patterns = list(THREE_CANDLE_SMART_ALLOWED_PATTERNS or [])
        pattern = str(candidate.get("pattern") or "")
        if allowed_patterns and pattern not in allowed_patterns:
            reasons.append(f"pattern_blocked:{pattern}")

        momentum_count = int(candidate.get("momentum_count", 0) or 0)
        if pattern == "momentum_continuation":
            continuation_exact = int(THREE_CANDLE_CONTINUATION_EXACT_MOMENTUM or 0)
            if continuation_exact <= 0 or momentum_count != continuation_exact:
                reasons.append(f"continuation_exact_blocked:{momentum_count}!= {continuation_exact}")
        elif pattern == "momentum_correction":
            # v1.02: 4, 5, 6, 7... are all valid as long as the base strategy minimum is met.
            if momentum_count < max(4, int(THREE_CANDLE_MOMENTUM_MIN)):
                reasons.append(f"correction_momentum_too_short:{momentum_count}")

        pair_allowed, pair_reason = _three_candle_smart_pair_allowed(str(candidate.get("pair") or ""))
        candidate["smart_pair_reason"] = pair_reason
        if not pair_allowed:
            reasons.append(pair_reason)

        if reasons:
            _three_candle_channel_state["smart_filter_skips"] = int(_three_candle_channel_state.get("smart_filter_skips", 0) or 0) + 1
            _three_candle_channel_state["last_smart_skip"] = " | ".join(reasons)[:300]
            return None

        candidate["smart_filter"] = True
        candidate["smart_pair_reason"] = pair_reason
        return candidate
    except Exception as e:
        logger.debug("Smart filter failed open: %s", e)
        return candidate

def build_three_candle_channel_summary(limit: int | None = None) -> str:
    effective_limit = int(limit) if limit and int(limit) > 0 else int(THREE_CANDLE_MEMORY_REPORT_LIMIT)
    effective_limit = max(1, effective_limit)
    records = _three_candle_fetch_result_records(limit=effective_limit)
    title = f"📊 ملخص قناة 3 شموع - آخر {effective_limit} نتيجة"

    direct_win = sum(1 for r in records if r.get("result_type") == "direct_win")
    mg_win = sum(1 for r in records if r.get("result_type") == "mg_win")
    loss = sum(1 for r in records if r.get("result_type") == "loss")
    draw = sum(1 for r in records if r.get("result_type") == "draw")
    cancelled = sum(1 for r in records if r.get("result_type") == "cancelled")
    total_closed = direct_win + mg_win + loss + draw
    wins = direct_win + mg_win
    win_rate = round((wins / total_closed) * 100, 1) if total_closed else 0

    return (
        f"{title}\n"
        "━━━━━━━━━━━━━━\n"
        f"📌 النتائج المحسوبة: {total_closed}\n"
        f"Win✅ مباشر: {direct_win}\n"
        f"Win✅. مضاعفة: {mg_win}\n"
        f"Lose💔: {loss}\n"
        f"🟰doji: {draw}\n"
        f"📈 نسبة الربح: {win_rate}%"
    )[:3900]



def _three_candle_normalize_live_currency_pair(name: str, symbol: str | None = None) -> str | None:
    """v1.03: normalize a live Quotex instrument only when the platform name is a fiat/fiat pair.

    This intentionally does NOT use OTC_CURRENCIES_ALLOWED_PAIRS. The platform's
    instruments/list is the source of truth for Three Candle. We trust the visible
    platform pair name for orientation because some Quotex internal symbols are reversed
    (for example a displayed USD/BRL pair may use an internal BRLUSD_otc symbol).
    """
    try:
        raw = str(name or "").strip().upper()
        match = re.search(r"\b([A-Z]{3})\s*/\s*([A-Z]{3})\b", raw)
        if not match:
            return None
        base, quote = match.group(1), match.group(2)
        if base not in FIAT_CURRENCY_CODES or quote not in FIAT_CURRENCY_CODES:
            return None
        if base == quote:
            return None
        return f"{base}/{quote} (OTC)"
    except Exception as e:
        logger.debug("Three Candle live pair normalization failed for %r/%r: %s", name, symbol, e)
        return None


def get_three_candle_pair_map() -> dict:
    """v1.03: build Three Candle universe directly from Quotex instruments/list.

    Rules:
    - only currently listed OTC instruments;
    - only fiat/fiat currency pairs inferred from Quotex's own display name;
    - payout must satisfy the effective Three Candle minimum (85% by default);
    - no legacy/manual allowlist and no OTC_LIVE_MAX_DYNAMIC_PAIRS cap;
    - every eligible symbol is followed dynamically so ticks/candles can accumulate.

    Other bot sections keep using get_otc_analysis_pair_map() unchanged.
    """
    live_map = {}
    try:
        if "quotex_otc_feed" not in globals():
            return live_map

        with quotex_otc_feed.lock:
            instruments = dict(quotex_otc_feed.instruments or {})

        min_payout = max(int(THREE_CANDLE_MIN_PAYOUT), int(THREE_CANDLE_SMART_MIN_PAYOUT))
        total_otc = 0
        currency_otc = 0
        eligible = 0
        best_payout_by_pair = {}
        symbols_to_follow = []

        for symbol, info in instruments.items():
            if not isinstance(info, dict):
                continue

            symbol = str(symbol or "").strip()
            if not symbol or not symbol.lower().endswith("_otc"):
                continue

            is_otc = bool(info.get("is_otc", False))
            if not is_otc:
                continue
            total_otc += 1

            pair = _three_candle_normalize_live_currency_pair(info.get("name"), symbol)
            if not pair:
                continue
            currency_otc += 1

            try:
                payout = int(float(info.get("payout", 0) or 0))
            except Exception:
                payout = 0
            if payout < min_payout:
                continue

            eligible += 1
            # Defensive duplicate handling: if Quotex exposes two internal symbols for the
            # same visible pair, keep the one with the higher current payout.
            previous_payout = int(best_payout_by_pair.get(pair, -1) or -1)
            if pair in live_map and payout <= previous_payout:
                continue

            live_map[pair] = symbol
            best_payout_by_pair[pair] = payout

        symbols_to_follow = list(dict.fromkeys(live_map.values()))
        for symbol in symbols_to_follow:
            quotex_otc_feed.add_symbol(symbol)

        min_candles = max(1, int(THREE_CANDLE_MOMENTUM_MIN) + 1)
        candles_ready = 0
        with quotex_otc_feed.lock:
            for symbol in symbols_to_follow:
                candles = quotex_otc_feed.candles.get(symbol) or {}
                last_tick = quotex_otc_feed.last_tick.get(symbol)
                if len(candles) >= min_candles and last_tick:
                    candles_ready += 1

        _three_candle_channel_state.update({
            "universe_instruments_seen": len(instruments),
            "universe_otc_seen": int(total_otc),
            "universe_currency_otc": int(currency_otc),
            "universe_payout_eligible": int(len(live_map)),
            "universe_candles_ready": int(candles_ready),
            "universe_min_payout": int(min_payout),
            "universe_last_update_at": now_iso(),
        })

        return live_map
    except Exception as e:
        _three_candle_channel_state["last_error"] = f"Three Candle universe: {e}"
        logger.exception("Could not build Three Candle live Quotex universe: %s", e)
        return live_map


