def otc_live_stats_control_ref():
    return system_ref().child("otc_live_channel_stats_control")


def get_otc_live_stats_reset_at() -> str:
    try:
        data = otc_live_stats_control_ref().get() or {}
        return str(data.get("reset_at", "") or "")
    except Exception:
        return ""


